const services = ["tally", "typeform", "google_forms"];
const settled = await Promise.allSettled(
  services.map(service => tools.mcp__lesson__read_service({ service }))
);

const inspected = settled.map((result, index) => {
  const service = services[index];
  if (result.status === "rejected") {
    return { service, status: "rejected", reason: String(result.reason) };
  }

  const textBlocks = (result.value?.content ?? [])
    .filter(block => block?.type === "text")
    .map(block => block.text);

  const parsed = textBlocks.map((raw, blockIndex) => {
    try {
      const value = JSON.parse(raw);
      return {
        blockIndex,
        parseStatus: "parsed",
        jsonType: Array.isArray(value) ? "array" : typeof value,
        keys: value && typeof value === "object" && !Array.isArray(value)
          ? Object.keys(value)
          : [],
        value
      };
    } catch (error) {
      return {
        blockIndex,
        parseStatus: "failed",
        error: String(error),
        raw
      };
    }
  });

  return { service, status: "fulfilled", parsed };
});

store("survey_help_settled", inspected);
text(inspected.map(item => ({
  service: item.service,
  status: item.status,
  reason: item.reason,
  blocks: item.parsed?.map(block => ({
    blockIndex: block.blockIndex,
    parseStatus: block.parseStatus,
    jsonType: block.jsonType,
    keys: block.keys,
    source: block.value?.source,
    title: block.value?.title,
    contentLength:
      typeof block.value?.content === "string" ? block.value.content.length :
      typeof block.value?.text === "string" ? block.value.text.length :
      typeof block.raw === "string" ? block.raw.length :
      null
  }))
})));

const inspected = load("survey_help_settled");
for (const item of inspected) {
  if (item.status === "rejected") {
    text(JSON.stringify({
      service: item.service,
      status: "rejected",
      reason: item.reason
    }));
    continue;
  }

  for (const block of item.parsed ?? []) {
    if (block.parseStatus === "failed") {
      text(JSON.stringify({
        service: item.service,
        status: "text_json_parse_failed",
        error: block.error,
        raw: block.raw
      }));
      continue;
    }

    const value = block.value;
    text(JSON.stringify({
      service: item.service,
      status: value?.error ? "tool_error" : "ok",
      source: value?.source ?? null,
      retrieved_at: value?.retrieved_at ?? null,
      evidence_text: value?.text ?? null,
      error: value?.error ?? null,
      tool: value?.tool ?? null
    }));
  }
}
